#include <bits/stdc++.h>using namespace std;using ll = long long; struct Node{         int open, close, matched;         Node() : open(0), close(0), matched(0) {}}; class SegTree{         int n;         vector<Node> seg; public:         SegTree(int n)         {                  this->n = n;                  seg.resize(4 * n);         }          Node Merge(const Node &left, const Node &right)         {                  Node res;                   int new_matches = min(left.open, right.close);                  res.matched = left.matched + right.matched + new_matches;                  res.open = left.open + right.open - new_matches;                  res.close = left.close + right.close - new_matches;                   return res;         }          void Build(int idx, int l, int r, const string &s)         {                  if (l == r)                  {                           if (s[l] == '(')                                    seg[idx].open = 1;                           else                                    seg[idx].close = 1;                           return;                  }                   int mid = (l + r) >> 1;                  Build(2 * idx + 1, l, mid, s);                  Build(2 * idx + 2, mid + 1, r, s);                   seg[idx] = Merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          Node Query(int idx, int l, int r, int ql, int qr)         {                  if (l > qr || r < ql)                           return Node();                   if (l >= ql && r <= qr)                           return seg[idx];                   int mid = (l + r) >> 1;                  Node left = Query(2 * idx + 1, l, mid, ql, qr);                  Node right = Query(2 * idx + 2, mid + 1, r, ql, qr);                   return Merge(left, right);         }}; int32_t main(){         ios::sync_with_stdio(false);         cin.tie(nullptr);          string s;         cin >> s;         int n = s.size();          SegTree seg(n);         seg.Build(0, 0, n - 1, s);          int q;         cin >> q;          while (q--)         {                  int l, r;                  cin >> l >> r;                  l--, r--;                   Node res = seg.Query(0, 0, n - 1, l, r);                  cout << 2 * res.matched << '\n';         }          return 0;}